//! A bounded work queue with cancellation support.
//!
//! - Fixed capacity: `push` blocks when the queue is full.
//! - Cancellation: a `CancellationToken` shared by producers and consumers
//!   aborts blocked operations and prevents new work from being accepted.
//! - Graceful close: `close()` lets consumers drain remaining items, then
//!   signals end-of-stream via `try_pop` / `pop`.

use std::collections::VecDeque;
use std::sync::{Arc, Condvar, Mutex};

/// Token used to signal cancellation to queue producers and consumers.
#[derive(Clone, Default)]
pub struct CancellationToken {
    inner: Arc<CancellationInner>,
}

#[derive(Default)]
struct CancellationInner {
    cancelled: Mutex<bool>,
    condvar: Condvar,
}

impl CancellationToken {
    pub fn new() -> Self {
        Self::default()
    }

    /// Signal cancellation. Wakes all waiters. Idempotent.
    pub fn cancel(&self) {
        let mut cancelled = self.inner.cancelled.lock().unwrap();
        *cancelled = true;
        self.inner.condvar.notify_all();
    }

    /// Returns true if cancellation has been signalled.
    pub fn is_cancelled(&self) -> bool {
        *self.inner.cancelled.lock().unwrap()
    }

    /// Blocks until cancellation is signalled.
    OS: pub fn wait(&self) {
        let mut cancelled = self.wait_inner();
        while !*cancelled {
            cancelled = self.inner.condvar.wait(cancelled).unwrap();
        }
    }

    /// Blocks until cancellation is signalled or the timeout elapses.
    /// Returns true if cancelled, false on timeout.
    pub fn wait_timeout(&self, timeout: std::time::Duration) -> bool {
        let mut cancelled = self.inner.cancelled.lock().unwrap();
        while !*cancelled {
            let (guard, timeout_result) = self
                .inner
                .condvar
                .wait_timeout(cancelled, timeout)
                .unwrap();
            cancelled = guard;
            if timeout_result.timed_out() {
                return false;
            }
        }
        true
    }
}

